import React, { useState, useEffect, useRef } from 'react';
import { casesAPI, openingsAPI } from '../services/api';
import ImageWithFallback from './ImageWithFallback';
import './CaseOpeningAnimation.css';

const CaseOpeningAnimation = ({ caseId, onComplete, onClose }) => {
  const [caseData, setCaseData] = useState(null);
  const [openingResult, setOpeningResult] = useState(null);
  const [loading, setLoading] = useState(true);
  const [animating, setAnimating] = useState(false);
  const [wonItem, setWonItem] = useState(null);
  const containerRef = useRef(null);

  // Fetch case details and perform opening
  useEffect(() => {
    const loadCaseAndOpen = async () => {
      try {
        // Fetch case details to get items
        const caseResponse = await casesAPI.getCaseById(caseId);
        setCaseData(caseResponse.data);

        // Perform the opening
        const openingResponse = await openingsAPI.openCase(caseId);
        setOpeningResult(openingResponse.data);
      } catch (error) {
        console.error('Error in case opening:', error);
      } finally {
        setLoading(false);
      }
    };

    loadCaseAndOpen();
  }, [caseId]);

  // When we have both case data and opening result, determine won item and start animation
  useEffect(() => {
    if (caseData && openingResult && !animating && !wonItem) {
      // Find the won item from case items
      const wonItemObj = caseData.items.find(item => item.id === openingResult.item_id);
      setWonItem(wonItemObj);
      // Start animation after a short delay
      const timer = setTimeout(() => {
        setAnimating(true);
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [caseData, openingResult, animating, wonItem]);

  // Animation end detection
  useEffect(() => {
    if (animating) {
      // Simulate animation duration: we'll use a timeout based on the animation length
      // The CSS animation duration is defined; we'll use 5 seconds for now
      const timer = setTimeout(() => {
        setAnimating(false);
        // Animation complete, call onComplete with won item
        if (wonItem) {
          onComplete(wonItem);
          // Optionally close after a short delay to show the won item
          const closeTimer = setTimeout(() => {
            if (onClose) onClose();
          }, 2000);
          return () => clearTimeout(closeTimer);
        }
      }, 5000); // Match CSS animation duration
      return () => clearTimeout(timer);
    }
  }, [animating, wonItem, onComplete, onClose]);

  if (loading) {
    return (
      <div className="opening-loading">
        <div className="spinner-border text-primary" role="status">
          <span className="visually-hidden">Loading...</span>
        </div>
      </div>
    );
  }

  if (!caseData) {
    return <div>Error loading case data</div>;
  }

  const getRarityClass = (rarity) => {
    if (!rarity) return 'bg-secondary';
    return `bg-${rarity.toLowerCase()}`;
  };

  return (
    <div className="opening-animation-container" ref={containerRef}>
      <div className="opening-header">
        <h3>Opening {caseData.name}</h3>
        <p className="text-muted">Case price: {caseData.price.toLocaleString()} €</p>
      </div>

      <div className="opening-slider">
        {caseData.items.map((item, index) => (
          <div key={item.id} className="opening-slide-item">
            <ImageWithFallback
              src={item.image_url}
              alt={item.name}
              className="item-image"
              style={{ width: '100px', height: '100px' }}
            />
            <div className="item-name">{item.name}</div>
            <div className={`item-rarity badge ${getRarityClass(item.rarity)}`}>
              {item.rarity}
            </div>
          </div>
        ))}
        {/* Duplicate items for seamless scrolling */}
        {caseData.items.map((item, index) => (
          <div key={item.id + '-clone'} className="opening-slide-item">
            <ImageWithFallback
              src={item.image_url}
              alt={item.name}
              className="item-image"
              style={{ width: '100px', height: '100px' }}
            />
            <div className="item-name">{item.name}</div>
            <div className={`item-rarity badge ${getRarityClass(item.rarity)}`}>
              {item.rarity}
            </div>
          </div>
        ))}
      </div>

      {animating && (
        <div className="opening-result">
          <div className="result-pointer"></div>
          <h4>And the winner is...</h4>
        </div>
      )}

      {!animating && wonItem && (
        <div className="opening-result">
          <div className="result-pointer"></div>
          <h4>Congratulations!</h4>
          <div className="won-item-display">
            <ImageWithFallback
              src={wonItem.image_url}
              alt={wonItem.name}
              className="won-item-image"
              style={{ width: '150px', height: '150px' }}
            />
            <div className="won-item-name">{wonItem.name}</div>
            <div className={`won-item-rarity badge ${getRarityClass(wonItem.rarity)}`}>
              {wonItem.rarity}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CaseOpeningAnimation;
